  "signal_basis": {
    "component_id": "C024.signal_basis",
    "value": "The proposed measurements track the fraction exceeding one hour and time-to-completion estimates that include unfinished exports, alongside assessment of median stability.",
    "scope": "Proposed outcome measurements, not results already obtained.",
    "provenance": {
