      "rationale": "P021 supplies the measurements and treatment of unfinished exports; P025 establishes their proposed status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C024.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
